import"./chunk-2NFLSA4Y.js";var r={reflection:{theory:{concept:"[[Reflection of light is the return of light into the same medium when it falls on the boundary with another medium.]] The law of reflection: the incident ray, the reflected ray and the normal to the surface lie in one plane, and the angle of reflection equals the angle of incidence; both angles are measured from the normal."},section:{normal:{title:"Measure from the normal",text:"The normal is an imaginary line perpendicular to the surface at the point where light hits. [[Both angles are measured from this line, not from the mirror.]] At 0\xB0 light retraces its path. At 45\xB0 the two ray arms form a right angle."},everyday:{title:"Mirrors and everyday light",text:"A smooth mirror reflects parallel rays in an orderly way, allowing a clear image to form. In a plane mirror the image appears as far behind the mirror as the object is in front. The image is virtual: the reflected rays do not actually pass behind the mirror. This experiment shows one ray rather than image formation."},diffuse:{title:"Why can we see paper?",text:"On a rough surface, tiny patches face different directions and have different normals. Each patch still obeys the law of reflection, but light leaves in many directions. This diffuse reflection helps us see paper from different positions. The simulation uses a smooth surface only."},try:{title:"Predict, then test",text:"Set the incident angle to 30\xB0 and predict the reflected angle. Now change the source distance and try again. Does the angle change? Next try 0\xB0 and 45\xB0. Use the solid incoming path, dashed outgoing path and arrows to distinguish the two rays."}},param:{angle:"Incident angle",distance:"Source to mirror distance",duration:"Animation duration",timeStep:"Animation timestep"},hint:{angle:"Measured from the dashed normal, not the mirror surface.",distance:"Distance along the incident ray to the point of incidence. The outgoing path shown has the same length.",duration:"Slows the marker for observation. This is not the real travel time of light."},preset:{normal:"Straight on",half:"45\xB0",grazing:"70\xB0"},measure:{incidence:"Angle of incidence",reflection:"Angle of reflection",surfaceAngle:"Angle to the mirror surface",betweenRays:"Angle between the ray arms",path:"Path traced by the marker",height:"Marker height above mirror",directionX:"Reflected unit direction: x",directionY:"Reflected unit direction: y"},view:{directions:"Ray directions",normal:"Normal",angles:"Angles",incident:"Incident \xB7 solid",reflected:"Reflected \xB7 dashed",mirror:"Plane mirror",slow:"Slowed illustration \xB7 not real light speed"},graph:{height:"Path geometry: height vs traced distance"},formula:{law:"Law of reflection",surface:"Angle measured from the surface",between:"Angle between the outward ray arms",vector:"Vector reflection: d is the incoming unit direction, r the reflected unit direction and n the unit normal"},assumption:{mirror:"Ideal smooth plane mirror in a uniform medium. Absorption, transmission and surface roughness are not modeled.",rays:"Geometrical optics: light is represented by thin rays. Diffraction, interference and image formation are not modeled; line thickness and marker size are not to scale.",animation:"The moving dot is a teaching marker, not a photon. Animation seconds are not physical light-travel time. The graph describes the path geometry, not the speed of light."},challenge:{normal:{title:"Return along the same path",description:"Run an experiment in which the reflected ray returns along the incident path.",hint:"Aim along the normal: the angle to it should be zero."},right:{title:"A right angle",description:"Run an experiment where the two ray arms form an angle of 90\xB0.",hint:"The normal divides that angle into two equal parts."},wide:{title:"A wide reflection",description:"Run an experiment with a reflected angle of at least 60\xB0 from the normal.",hint:"Increase the incident angle: the reflected angle follows it."},surface:{title:"Which reference line?",description:"Make the reflected ray form 30\xB0 with the mirror surface and run the experiment.",hint:"The surface and the normal are perpendicular: subtract 30\xB0 from 90\xB0."},path:{title:"Eight metres of path",description:"Let the marker complete a total path of 8 m.",hint:"The two displayed path segments have equal length. Change the source distance."}}}},n={sim:r};export{n as default,r as sim};
